:root {
  --bg-base: #0d0d0f;
  --bg-surface: #141418;
  --bg-elevated: #1c1c22;
  --bg-card: #1e1e26;
  --bg-overlay: rgba(13, 13, 15, 0.85);

  --accent-primary: #e8c87a;
  --accent-primary-dark: #c9a84c;
  --accent-secondary: #7a9ee8;
  --accent-danger: #e87a7a;
  --accent-success: #7ae8a8;

  --text-primary: #f0ede8;
  --text-secondary: #a09890;
  --text-muted: #5c5852;
  --text-inverse: #0d0d0f;

  --border-subtle: rgba(255, 255, 255, 0.06);
  --border-default: rgba(255, 255, 255, 0.1);
  --border-strong: rgba(255, 255, 255, 0.18);

  --shadow-sm: 0 1px 3px rgba(0,0,0,0.5);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.6);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.7);
  --shadow-glow: 0 0 24px rgba(232, 200, 122, 0.15);

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  --focus-ring: 0 0 0 3px rgba(232, 200, 122, 0.45);
}

/* ===== RESET & BASE ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

/* ===== FOCUS STYLES ===== */
:focus-visible {
  outline: 2px solid var(--accent-primary);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ===== SKIP LINK ===== */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 1rem;
  z-index: 9999;
  background: var(--accent-primary);
  color: var(--text-inverse);
  padding: 0.75rem 1.25rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 0.875rem;
  transition: top var(--transition-fast);
}

.skip-link:focus {
  top: 1rem;
  outline: 2px solid var(--bg-base);
  outline-offset: 2px;
}

/* ===== UTILITIES ===== */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ===== ANNOUNCEMENT BANNER ===== */
.announcement-bar {
  background: var(--accent-primary);
  color: var(--text-inverse);
  text-align: center;
  padding: 0.5rem 1rem;
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.02em;
}

/* ===== HEADER ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--bg-overlay);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border-subtle);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  height: 68px;
}

/* Logo */
.site-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
  text-decoration: none;
}

.site-logo__mark {
  width: 36px;
  height: 36px;
  background: var(--accent-primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.1rem;
  color: var(--text-inverse);
  letter-spacing: -0.03em;
}

.site-logo__name {
  font-family: var(--font-display);
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.01em;
}

/* Primary Nav */
.primary-nav {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.primary-nav__link {
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background var(--transition-fast);
  white-space: nowrap;
}

.primary-nav__link:hover,
.primary-nav__link[aria-current="page"] {
  color: var(--text-primary);
  background: var(--border-subtle);
}

/* Header Actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.header-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition-fast), background var(--transition-fast);
  background: transparent;
}

.header-btn:hover {
  color: var(--text-primary);
  background: var(--border-subtle);
}

.header-btn svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.75;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.cart-badge {
  position: absolute;
  top: 4px;
  right: 4px;
  background: var(--accent-primary);
  color: var(--text-inverse);
  font-size: 0.6rem;
  font-weight: 700;
  min-width: 16px;
  height: 16px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  padding: 0 3px;
}

.mobile-menu-btn {
  display: none;
}

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: min(90vh, 720px);
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--bg-surface);
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-bg-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.35;
}

.hero-bg-gradient {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    rgba(13, 13, 15, 0.95) 0%,
    rgba(13, 13, 15, 0.7) 45%,
    rgba(13, 13, 15, 0.3) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 620px;
  padding: 4rem 0;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(232, 200, 122, 0.12);
  border: 1px solid rgba(232, 200, 122, 0.25);
  color: var(--accent-primary);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.375rem 0.875rem;
  border-radius: var(--radius-full);
  margin-bottom: 1.5rem;
}

.hero-eyebrow::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-primary);
}

.hero-heading {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 1.25rem;
}

.hero-heading em {
  font-style: normal;
  color: var(--accent-primary);
}

.hero-subheading {
  font-size: 1.0625rem;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 480px;
  margin-bottom: 2.25rem;
}

.hero-actions {
  display: flex;
  gap: 0.875rem;
  flex-wrap: wrap;
  align-items: center;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all var(--transition-base);
  white-space: nowrap;
  cursor: pointer;
  border: none;
  font-family: inherit;
  text-decoration: none;
  letter-spacing: 0.01em;
}

.btn:focus-visible {
  outline: 2px solid var(--accent-primary);
  outline-offset: 3px;
}

.btn-primary {
  background: var(--accent-primary);
  color: var(--text-inverse);
  box-shadow: 0 2px 12px rgba(232, 200, 122, 0.3);
}

.btn-primary:hover {
  background: var(--accent-primary-dark);
  box-shadow: 0 4px 20px rgba(232, 200, 122, 0.4);
  transform: translateY(-1px);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}

.btn-ghost:hover {
  background: var(--border-subtle);
  border-color: var(--border-strong);
}

.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.8125rem;
}

.btn-icon-after svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform var(--transition-fast);
}

.btn:hover .btn-icon-after svg {
  transform: translateX(3px);
}

/* ===== SECTION HEADERS ===== */
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.section-label {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-primary);
  margin-bottom: 0.5rem;
}

.section-label::before {
  content: '';
  display: block;
  width: 20px;
  height: 2px;
  background: var(--accent-primary);
  border-radius: 2px;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.625rem, 3vw, 2.25rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.section-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent-primary);
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0;
  transition: gap var(--transition-fast), opacity var(--transition-fast);
  white-space: nowrap;
}

.section-link:hover {
  opacity: 0.8;
  gap: 0.625rem;
}

.section-link svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ===== SECTION SPACING ===== */
.section {
  padding: 4.5rem 0;
}

.section--dark {
  background: var(--bg-surface);
}

.section--elevated {
  background: var(--bg-elevated);
}

/* ===== PRODUCT CARD ===== */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base), border-color var(--transition-base);
  position: relative;
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--border-default);
}

.product-card__image-wrap {
  position: relative;
  aspect-ratio: 4 / 3;
  background: var(--bg-elevated);
  overflow: hidden;
}

.product-card__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.product-card:hover .product-card__image {
  transform: scale(1.05);
}

.product-card__badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.25rem 0.625rem;
  border-radius: var(--radius-full);
  line-height: 1.4;
}

.badge--new {
  background: var(--accent-secondary);
  color: #fff;
}

.badge--sale {
  background: var(--accent-danger);
  color: #fff;
}

.badge--limited {
  background: var(--accent-primary);
  color: var(--text-inverse);
}

.product-card__wishlist {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  width: 34px;
  height: 34px;
  background: rgba(13,13,15,0.7);
  backdrop-filter: blur(8px);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  opacity: 0;
  transform: scale(0.8);
  border: 1px solid var(--border-subtle);
}

.product-card:hover .product-card__wishlist,
.product-card__wishlist:focus-visible {
  opacity: 1;
  transform: scale(1);
}

.product-card__wishlist:hover {
  color: var(--accent-danger);
  background: rgba(232, 122, 122, 0.15);
  border-color: rgba(232, 122, 122, 0.3);
}

.product-card__wishlist svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
}

.product-card__wishlist[aria-pressed="true"] svg {
  fill: var(--accent-danger);
  stroke: var(--accent-danger);
}

.product-card__body {
  padding: 1rem 1.125rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  flex: 1;
}

.product-card__category {
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.product-card__name {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.4;
}

.product-card__rating {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.stars {
  display: flex;
  gap: 2px;
}

.star {
  width: 12px;
  height: 12px;
  fill: var(--accent-primary);
  color: var(--accent-primary);
}

.star--empty {
  fill: none;
  stroke: var(--text-muted);
  stroke-width: 1.5;
}

.star--half {
  fill: var(--accent-primary);
  clip-path: inset(0 50% 0 0);
}

.rating-count {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.product-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: auto;
}

.product-card__price {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
}

.price-current {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text-primary);
}

.price-original {
  font-size: 0.8125rem;
  color: var(--text-muted);
  text-decoration: line-through;
}

.price-save {
  font-size: 0.6875rem;
  font-weight: 700;
  color: var(--accent-success);
  letter-spacing: 0.04em;
}

.product-card__add-btn {
  width: 36px;
  height: 36px;
  min-width: 36px;
  border-radius: var(--radius-md);
  background: var(--accent-primary);
  color: var(--text-inverse);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  border: none;
  cursor: pointer;
}

.product-card__add-btn:hover {
  background: var(--accent-primary-dark);
  transform: scale(1.08);
}

.product-card__add-btn:active {
  transform: scale(0.95);
}

.product-card__add-btn svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  pointer-events: none;
}

/* ===== DEALS SECTION ===== */
.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
}

.deal-card {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  min-height: 280px;
  display: flex;
  align-items: flex-end;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.deal-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.deal-card--tall {
  grid-row: span 2;
  min-height: 588px;
}

.deal-card__image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.4;
  transition: transform var(--transition-slow), opacity var(--transition-base);
}

.deal-card:hover .deal-card__image {
  transform: scale(1.04);
  opacity: 0.5;
}

.deal-card__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to top,
    rgba(13, 13, 15, 0.96) 0%,
    rgba(13, 13, 15, 0.5) 50%,
    rgba(13, 13, 15, 0.1) 100%
  );
}

.deal-card__content {
  position: relative;
  z-index: 1;
  padding: 1.75rem;
  width: 100%;
}

.deal-card__discount {
  display: inline-flex;
  align-items: center;
  background: var(--accent-danger);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.3rem 0.75rem;
  border-radius: var(--radius-full);
  margin-bottom: 0.75rem;
}

.deal-card__title {
  font-family: var(--font-display);
  font-size: clamp(1.25rem, 2.5vw, 1.625rem);
  font-weight: 700;
  line-height: 1.25;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.deal-card__desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
  line-height: 1.6;
}

.countdown {
  display: flex;
  gap: 0.625rem;
  margin-bottom: 1.25rem;
  align-items: center;
}

.countdown__label {
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-right: 0.25rem;
}

.countdown__unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  padding: 0.375rem 0.625rem;
  min-width: 44px;
}

.countdown__value {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  margin-bottom: 2px;
}

.countdown__label-unit {
  font-size: 0.5625rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.countdown__sep {
  color: var(--text-muted);
  font-weight: 700;
  font-size: 1rem;
  margin-top: -4px;
}

/* ===== CATEGORIES ===== */
.categories-scroll {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1rem;
}

.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  padding: 1.25rem 1rem;
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
  text-decoration: none;
  color: var(--text-secondary);
  position: relative;
  overflow: hidden;
}

.category-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(232,200,122,0.05), transparent 60%);
  opacity: 0;
  transition: opacity var(--transition-base);
}

.category-card:hover {
  border-color: rgba(232, 200, 122, 0.3);
  color: var(--text-primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md), var(--shadow-glow);
}

.category-card:hover::before {
  opacity: 1;
}

.category-card__icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border-subtle);
  transition: all var(--transition-base);
}

.category-card:hover .category-card__icon {
  background: rgba(232, 200, 122, 0.1);
  border-color: rgba(232, 200, 122, 0.2);
}

.category-card__name {
  font-size: 0.8125rem;
  font-weight: 600;
  text-align: center;
  line-height: 1.3;
}

.category-card__count {
  font-size: 0.6875rem;
  color: var(--text-muted);
}

/* ===== EDITORIAL ===== */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 1.25rem;
}

.editorial-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition-base), box-shadow var(--transition-base);
}

.editorial-card:hover {
  border-color: var(--border-default);
  box-shadow: var(--shadow-md);
}

.editorial-card__image-wrap {
  position: relative;
  aspect-ratio: 16/9;
  overflow: hidden;
  background: var(--bg-elevated);
}

.editorial-card--small .editorial-card__image-wrap {
  aspect-ratio: 3/2;
}

.editorial-card__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.editorial-card:hover .editorial-card__image {
  transform: scale(1.04);
}

.editorial-card__category-tag {
  position: absolute;
  top: 1rem;
  left: 1rem;
  background: rgba(13,13,15,0.8);
  backdrop-filter: blur(8px);
  color: var(--accent-primary);
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.3rem 0.75rem;
  border-radius: var(--radius-full);
  border: 1px solid rgba(232,200,122,0.25);
}

.editorial-card__body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  flex: 1;
}

.editorial-card__title {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--text-primary);
}

.editorial-card--large .editorial-card__title {
  font-size: 1.5rem;
}

.editorial-card__excerpt {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

.editorial-card__meta {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: auto;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border-subtle);
}

.editorial-card__author-avatar {
  width: 28px;
  height: 28px;
