+  const palettes = [
+    ['#2a1f3d', '#4a2d6b', '#7a5bb5'],
+    ['#1f2d3d', '#2d4a6b', '#5b8bb5'],
+    ['#3d2a1f', '#6b4a2d', '#b58b5b'],
+    ['#1f3d2a', '#2d6b4a', '#5bb58b'],
+    ['#3d1f2a', '#6b2d4a', '#b55b8b'],
+    ['#2a3d1f', '#4a6b2d', '#8bb55b'],
+  ];
+
+  const palette = palettes[seed % palettes.length];
+  const gradient = ctx.createLinearGradient(0, 0, width, height);
+  gradient.addColorStop(0, palette[0]);
+  gradient.addColorStop(0.5, palette[1]);
+  gradient.addColorStop(1, palette[2]);
+
+  ctx.fillStyle = gradient;
+  ctx.fillRect(0, 0, width, height);
+
+  // Add subtle noise texture
+  ctx.globalAlpha = 0.06;
+  for (let i = 0; i < 800; i++) {
+    const x = Math.random() * width;
+    const y = Math.random() * height;
+    ctx.fillStyle = Math.random() > 0.5 ? '#fff' : '#000';
+    ctx.fillRect(x, y, 1.5, 1.5);
+  }
+  ctx.globalAlpha = 1;
+
+  return canvas.toDataURL('image/png');
+}
+
+/**
+ * Fills all [data-placeholder] images with generated placeholders.
+ */
+function initPlaceholders() {
+  const imgs = document.querySelectorAll('img[data-placeholder]');
+  imgs.forEach((img, i) => {
+    const seed = parseInt(img.dataset.placeholder, 10) || i;
+    const w = parseInt(img.dataset.w, 10) || 400;
+    const h = parseInt(img.dataset.h, 10) || 300;
+    const uri = generatePlaceholder(seed, w, h);
+    img.src = uri;
+  });
+}
+
+/* ===== COUNTDOWN TIMER ===== */
+function initCountdowns() {
+  document.querySelectorAll('[data-countdown]').forEach(el => {
+    const endTime = Date.now() + parseInt(el.dataset.countdown, 10) * 1000;
+
+    function update() {
+      const remaining = Math.max(0, Math.floor((endTime - Date.now()) / 1000));
+      const h = Math.floor(remaining / 3600);
+      const m = Math.floor((remaining % 3600) / 60);
+      const s = remaining % 60;
+
+      const pad = n => String(n).padStart(2, '0');
+      const hEl = el.querySelector('[data-unit="h"]');
+      const mEl = el.querySelector('[data-unit="m"]');
+      const sEl = el.querySelector('[data-unit="s"]');
+      if (hEl) hEl.textContent = pad(h);
+      if (mEl) mEl.textContent = pad(m);
+      if (sEl) sEl.textContent = pad(s);
+
+      if (remaining > 0) requestAnimationFrame(update);
+    }
+
+    update();
+  });
+}
+
+/* ===== CART STATE ===== */
+const cartState = {
+  items: [],
+  get count() { return this.items.length; },
+};
+
+function updateCartBadge() {
+  const badge = document.getElementById('cart-badge');
+  const count = cartState.count;
+  if (badge) {
+    badge.textContent = count;
+    badge.hidden = count === 0;
+    badge.setAttribute('aria-label', `${count} item${count !== 1 ? 's' : ''} in cart`);
+  }
+}
+
+function addToCart(productId, productName) {
+  cartState.items.push({ id: productId, name: productName });
+  updateCartBadge();
+  announce(`${productName} added to cart`);
+}
+
+/* ===== WISHLIST STATE ===== */
+const wishlistState = new Set();
+
+function toggleWishlist(btn, productId, productName) {
+  const isWished = wishlistState.has(productId);
+  if (isWished) {
+    wishlistState.delete(productId);
+    btn.setAttribute('aria-pressed', 'false');
+    btn.setAttribute('aria-label', `Add ${productName} to wishlist`);
+    announce(`${productName} removed from wishlist`);
+  } else {
+    wishlistState.add(productId);
+    btn.setAttribute('aria-pressed', 'true');
+    btn.setAttribute('aria-label', `Remove ${productName} from wishlist`);
+    announce(`${productName} added to wishlist`);
+  }
+}
+
+/* ===== LIVE ANNOUNCER ===== */
+function announce(message) {
+  const region = document.getElementById('live-region');
+  if (region) {
+    region.textContent = '';
+    // Small delay to ensure screen readers pick up the change
+    requestAnimationFrame(() => {
+      requestAnimationFrame(() => {
+        region.textContent = message;
+      });
+    });
+  }
+}
+
+/* ===== MOBILE MENU ===== */
+function initMobileMenu() {
+  const btn = document.getElementById('mobile-menu-btn');
+  const nav = document.getElementById('mobile-nav');
+  const overlay = document.getElementById('mobile-nav-overlay');
+  const closeBtn = document.getElementById('mobile-nav-close');
+
+  if (!btn || !nav) return;
+
+  function open() {
+    nav.classList.add('is-open');
+    overlay.classList.add('is-open');
+    btn.setAttribute('aria-expanded', 'true');
+    nav.removeAttribute('hidden');
+    closeBtn.focus();
+    document.body.style.overflow = 'hidden';
+  }
+
+  function close() {
+    nav.classList.remove('is-open');
+    overlay.classList.remove('is-open');
+    btn.setAttribute('aria-expanded', 'false');
+    btn.focus();
+    document.body.style.overflow = '';
+  }
+
+  btn.addEventListener('click', open);
+  closeBtn.addEventListener('click', close);
+  overlay.addEventListener('click', close);
+
+  nav.addEventListener('keydown', e => {
+    if (e.key === 'Escape') close();
+  });
+}
+
+/* ===== NEWSLETTER FORM ===== */
+function initNewsletter() {
+  const form = document.getElementById('newsletter-form');
+  if (!form) return;
+
+  const input = form.querySelector('#newsletter-email');
+  const message = document.getElementById('newsletter-message');
+
+  form.addEventListener('submit', e => {
+    e.preventDefault();
+
+    const val = input.value.trim();
+    const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+    if (!val) {
+      setNewsletterError('Please enter your email address.');
+      input.focus();
+      return;
+    }
+
+    if (!emailRe.test(val)) {
+      setNewsletterError('Please enter a valid email address.');
+      input.focus();
+      return;
+    }
+
+    input.setAttribute('aria-invalid', 'false');
+    message.className = 'newsletter__message newsletter__message--success';
+    message.textContent = '🎉 You\'re in! Check your inbox for a welcome offer.';
+    announce('You have successfully subscribed to the newsletter.');
+    form.querySelector('button[type="submit"]').disabled = true;
+    input.value = '';
+  });
+
+  function setNewsletterError(text) {
+    input.setAttribute('aria-invalid', 'true');
+    message.className = 'newsletter__message newsletter__message--error';
+    message.textContent = text;
+    announce(text);
+  }
+}
+
+/* ===== ADD TO CART BUTTONS ===== */
+function initAddToCart() {
+  document.querySelectorAll('[data-add-to-cart]').forEach(btn => {
+    btn.addEventListener('click', () => {
+      const id = btn.dataset.addToCart;
+      const name = btn.dataset.productName || 'Product';
+      addToCart(id, name);
+
+      // Brief "added" feedback
+      const originalLabel = btn.getAttribute('aria-label');
+      btn.setAttribute('aria-label', 'Added!');
+      btn.style.background = 'var(--accent-success)';
+      setTimeout(() => {
+        btn.setAttribute('aria-label', originalLabel);
+        btn.style.background = '';
+      }, 1000);
+    });
+  });
+}
+
+/* ===== WISHLIST BUTTONS ===== */
+function initWishlistButtons() {
+  document.querySelectorAll('[data-wishlist]').forEach(btn => {
+    btn.addEventListener('click', () => {
+      const id = btn.dataset.wishlist;
+      const name = btn.dataset.productName || 'Product';
+      toggleWishlist(btn, id, name);
+    });
+  });
+}
+
+/* ===== SCROLL ANIMATIONS ===== */
+function initScrollAnimations() {
+  if (!('IntersectionObserver' in window)) return;
+  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
+
+  const style = document.createElement('style');
+  style.textContent = `
+    .animate-in {
+      opacity: 0;
+      transform: translateY(20px);
+      transition: opacity 0.5s ease, transform 0.5s ease;
+    }
+    .animate-in.is-visible {
+      opacity: 1;
+      transform: none;
+    }
+  `;
+  document.head.appendChild(style);
+
+  const targets = document.querySelectorAll(
+    '.product-card, .deal-card, .editorial-card, .category-card, .trust-item'
+  );
+
+  targets.forEach(el => el.classList.add('animate-in'));
+
+  const observer = new IntersectionObserver(entries => {
+    entries.forEach(entry => {
+      if (entry.isIntersecting) {
+        entry.target.classList.add('is-visible');
+        observer.unobserve(entry.target);
+      }
+    });
+  }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });
+
+  targets.forEach(el => observer.observe(el));
+}
+
+/* ===== INIT ===== */
+document.addEventListener('DOMContentLoaded', () => {
+  initPlaceholders();
+  initCountdowns();
+  initMobileMenu();
+  initNewsletter();
+  initAddToCart();
+  initWishlistButtons();
+  initScrollAnimations();
+  updateCartBadge();
+});
+
')
